SourceCode.Declaration:
/// <summary>
/// Contract class for importing messages
/// </summary>
[DataContract]
public class OMGInboundMessageContract
{
    OMGMessageGUID      messageGUID;
    OMGMessageName      messageName;
    OMGMessageTypeId    messageTypeId;
    str                 message;
    DataAreaId          company;
    OMGBase64Encoded    base64Encoded;
    TransDateTime       sourceDateTime;
    boolean             decodeOnInsert;

}

Method.Source:
[DataMember('Base64Encoded')]
public OMGBase64Encoded parmBase64Encoded(OMGBase64Encoded    _base64Encoded = base64Encoded)
{
    base64Encoded = _base64Encoded;
    return base64Encoded;
}

[DataMember('DecodeOnInsert')]
public boolean parmDecodeOnInsert(boolean   _decodeOnInsert = decodeOnInsert)
{
    decodeOnInsert = _decodeOnInsert;
    return decodeOnInsert;
}

[DataMember('Company')]
public DataAreaId parmCompany(DataAreaId    _company = company)
{
    company = _company;
    return company;
}

[DataMember('MessageGUID')]
public OMGMessageGUID parmMessageGUID(OMGMessageGUID    _messageGUID = messageGUID)
{
    messageGUID = _messageGUID;
    return messageGUID;
}

[DataMember('Name')]
public OMGMessageName parmMessageName(OMGMessageName    _messageName = messageName)
{
    messageName = _messageName;
    return messageName;
}

[DataMember('MessageTypeId')]
public OMGMessageTypeId parmMessageTypeId(OMGMessageTypeId _messageTypeId  = messageTypeId)
{
    messageTypeId = _messageTypeId;
    return messageTypeId;
}

[DataMember('Message')]
public str parmMessage(str    _message = message)
{
    message = _message;
    return message;
}

[DataMember('SourceDateTime')]
public TransDateTime parmSourceDateTime(TransDateTime    _sourceDateTime = sourceDateTime)
{
    sourceDateTime = _sourceDateTime;
    return sourceDateTime;
}
